request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
binary-002

Cluster Arity:
2

Cluster Members:
[
  {
    "name": "REPRODUCES_STIPULATED_WORKFLOW",
    "definition": "The action replays the exact procedure stipulated by the task or requester, mirroring its steps instead of substituting a proxy check, so that the stipulated procedure itself is validated.",
    "parameters": [
      {
        "name": "validation_reasoning",
        "type": "reasoning",
        "description": "The reasoning stating that the stipulated procedure itself is being replayed for validation."
      },
      {
        "name": "replay_action",
        "type": "action",
        "description": "The action whose operations reproduce the stipulated steps."
      }
    ],
    "assertion_conditions": [
      "The reasoning states that the procedure the requester is expected to run is itself being replayed in order to validate it.",
      "The action contains the same operations, in the same sequence or spirit, as the stipulated procedure rather than an indirect substitute such as a status query or configuration inspection."
    ],
    "exclusion_conditions": [
      "The action performs an equivalent but different check that does not reproduce the stipulated sequence.",
      "The reasoning does not connect the action to the stipulated procedure.",
      "The action merely inspects state or configuration without exercising the user-facing workflow."
    ]
  },
  {
    "name": "MIRRORS_REFERENCE_OPERATION_ORDER",
    "definition": "The reasoning deliberately adopts the evaluation or accumulation order of a reference implementation exposed by an observation, so that the new implementation reproduces the reference's numerical results within the required tolerance.",
    "parameters": [
      {
        "name": "reasoning",
        "type": "reasoning",
        "description": "The agent text stating that the new computation follows the reference implementation's order of operations in order to match its results."
      },
      {
        "name": "observation",
        "type": "observation",
        "description": "The observation containing the reference implementation or its computational procedure, whose operation order can be identified."
      }
    ],
    "assertion_conditions": [
      "The observation contains an implementation or computational procedure whose sequence of operations can be identified.",
      "The reasoning explicitly states that the new computation reproduces that same order or sequence of operations.",
      "The reasoning links the adopted order to matching the reference results within the required tolerance."
    ],
    "exclusion_conditions": [
      "The reasoning only states that results must match, without any reference to reproducing the reference's operation order.",
      "The referenced content does not describe an implementation or computational procedure.",
      "The reasoning selects a materially different order for speed or convenience without claiming to reproduce the reference's results through it."
    ]
  }
]

