["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER",
  "definition": "The reasoning deliberately commits to reproducing the identifiable steps or operations of a stipulated workflow or reference implementation presented in the available procedure evidence, rather than substituting an equivalent check or merely aligning outcomes, so that the stipulated procedure itself is validated or the reference results are matched within the required tolerance.",
  "parameters": [
    {
      "name": "reproduction_reasoning",
      "type": "reasoning",
      "description": "The reasoning that identifies a stipulated procedure or reference implementation and states that its steps or operation order are to be reproduced for validation or result matching."
    },
    {
      "name": "procedure_evidence",
      "type": "observation",
      "description": "The observed or available presentation or execution of the stipulated workflow or reference implementation, whose identifiable steps or order of operations are to be reproduced."
    }
  ],
  "assertion_conditions": [
    "The reasoning identifies a stipulated procedure or reference implementation or operation order that is to be reproduced rather than replaced by an unrelated or merely equivalent proxy.",
    "The procedure evidence presents identifiable steps, operations, or an ordering that can be followed.",
    "The reasoning explicitly connects reproducing the same steps or operation order to validating the stipulated procedure or matching the reference results within the required tolerance."
  ],
  "exclusion_conditions": [
    "The reasoning only requires the final result to match without committing to reproducing the reference's steps or operation order.",
    "The procedure evidence does not present an identifiable procedure, implementation, or sequence of operations.",
    "The reasoning or resulting behavior performs only a status query, configuration inspection, or equivalent substitute that does not exercise or reproduce the stipulated workflow.",
    "A materially different procedure or order is selected for speed or convenience without a claim that it reproduces the stipulated or reference procedure."
  ]
}

